// Backpack.cpp
// This source file implements the functionality of the Backpack class.
// Also handles and emits all of the events generated by the backpack.
// The backpack includes and has access to its own:
// Inventory Class, TaskManager Class and eventGenerator Class.

#include "Backpack.h"
#include <iostream>
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Backpack constructor initializes the Backpack with a reference to an Inventory 
// object and initializes the TaskManager with the same Inventory reference.
Backpack::Backpack(Inventory& inventory)
    : inventory(inventory),
      taskManager(inventory)
{
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Initializes the Backpack system, preparing it for operation.
// Sets the initial state of the Backpack to IDLE.
void Backpack::begin()
{
    state = BackpackState::IDLE;
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Returns the current state of the Backpack.
BackpackState Backpack::getState() const
{
    return state;
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Registers a task with the backpacks associated TaskManager
// Returns true if the task registers sucessfully
bool Backpack::registerTask(const Task& task)
{
    return taskManager.registerTask(task);
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Start a task of the specified type using the TaskManager.
// Returns true if the task was successfully started, false otherwise.
bool Backpack::startTask(TaskType type)
{

    // If the backpack is not in the IDLE state, we cannot start a new task.
    if (state != BackpackState::IDLE)
    {
        return false;
    }

    // Attempt to start the task with the specified type.
    if (!taskManager.startTask(type))
    {
        // If the task could not be started 
        // (e.g., it is not registered, or another task is active), return false.
        return false;
    }
    else 
    {
    // Generate Event : Task started.
    BackpackEvent event{};

    event.type = EventType::TaskStarted;
    event.item = ItemType::Unknown;
    event.task = type;

    eventGenerator.emit(event);

    state = BackpackState::CHECKING_INVENTORY;

    // After starting the task, immediately check the inventory.
    // If the task is complete, the state will be updated to TASK_REMINDER;
    // otherwise, it will be updated to ACQUIRING_ITEMS.
    checkInventory();
    
    return true;

    }
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Stop the currently active task using the TaskManager.
// Resets the Backpack state to IDLE.
void Backpack::stopTask()
{
    BackpackEvent event{};

    event.type = EventType::TaskStopped;
    event.item = ItemType::Unknown;
    event.task = taskManager.getCurrentTask();

    eventGenerator.emit(event);

    taskManager.stopTask();
    state = BackpackState::IDLE;  
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Checks the inventory to determine if the current task is complete or 
// if items are still needed.
// Updates the Backpack state accordingly.
void Backpack::checkInventory()
{
    if (taskManager.isTaskComplete())
    {
        // Switch to user reminder state if the task is complete.
        BackpackEvent event{};

        event.type = EventType::TaskComplete;
        event.item = ItemType::Unknown;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);

        state = BackpackState::TASK_REMINDER;

        event.type = EventType::TaskReminder;
        event.item = ItemType::Unknown;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);

    }
    else
    {
        state = BackpackState::ACQUIRING_ITEMS;
        
        // Generate event : Item Required.
        BackpackEvent event{};

        event.type = EventType::ItemRequired;
        event.item = taskManager.getNextRequiredItem();
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);
    }
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Add item to the Backpack's inventory when it is scanned.
// This function should be called when an item is scanned into the backpack.
// Takes in the tagID (e.g. RFID Tag = 0x1234) 

void Backpack::itemAdded(uint32_t tagID)
{
    // Check whether this tag is already registered.
    Item* item = inventory.findItem(tagID);

    // An unregistered tag can still be tracked as an unknown item.
    if (item == nullptr)
    {
        // An unregistered tag needs a new inventory slot.
        // If the inventory is full, stop without reporting
        // the tag as an unknown RFID.
        if (inventory.getItemCount() >= MAX_ITEMS)
        {
            BackpackEvent event{};
            event.type = EventType::InventoryFull;
            event.item = ItemType::Unknown;
            event.task = taskManager.getCurrentTask();
            eventGenerator.emit(event);
            return;
        }

        if (!inventory.registerItem(tagID, ItemType::Unknown))
        {
            BackpackEvent event{};
            event.type = EventType::UnknownRFID;
            event.item = ItemType::Unknown;
            event.task = taskManager.getCurrentTask();
            eventGenerator.emit(event);
            return;
        }
    }

    // Retrieve the item's type after registration.
    ItemType itemType = inventory.getItemType(tagID);

    // Update the inventory before generating a normal item event.
    if (!inventory.addItem(tagID))
    {
        BackpackEvent event{};
        event.type = EventType::UnknownRFID;
        event.item = ItemType::Unknown;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);
        return;
    }

    // Unknown items are tracked, but do not participate in task logic.
    if (itemType == ItemType::Unknown)
    {
        BackpackEvent event{};
        event.type = EventType::UnknownRFID;
        event.item = ItemType::Unknown;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);
        return;
    }

    // Handle recognised items while acquiring task items.
    if (state == BackpackState::ACQUIRING_ITEMS)
    {
        BackpackEvent event{};

        if (!taskManager.isItemRequired(itemType))
        {
            event.type = EventType::ItemNotRequired;
        }
        else
        {
            event.type = EventType::ItemAcquired;
        }

        event.item = itemType;
        event.task = taskManager.getCurrentTask();
        eventGenerator.emit(event);

        // Recheck progress after the inventory update.
        checkInventory();
    }
    else
    {
        // A recognised item was added outside the acquisition state.
        BackpackEvent event{};
        event.type = EventType::ItemAdded;
        event.item = itemType;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);
    }
}

// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Remove item from the backpack (sets this item location flag = outside)

void Backpack::itemRemoved(uint32_t tagID)
{
    // Find the tag before attempting to remove it.
    Item* item = inventory.findItem(tagID);

    // A tag that is not registered cannot be removed from inventory.
    if (item == nullptr)
    {
        BackpackEvent event{};
        event.type = EventType::UnknownRFID;
        event.item = ItemType::Unknown;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);
        return;
    }

    // Save the type before updating the item's location.
    ItemType itemType = item->type;

    // An unidentified item is tracked, but has no normal item event.
    if (itemType == ItemType::Unknown)
    {
        if (inventory.removeItem(tagID))
        {
            BackpackEvent event{};
            event.type = EventType::UnknownRFID;
            event.item = ItemType::Unknown;
            event.task = taskManager.getCurrentTask();

            eventGenerator.emit(event);
        }

        return;
    }

    // Only generate ItemRemoved if the inventory operation succeeds.
    if (!inventory.removeItem(tagID))
    {
        return;
    }

    BackpackEvent event{};
    event.type = EventType::ItemRemoved;
    event.item = itemType;
    event.task = taskManager.getCurrentTask();

    eventGenerator.emit(event);

    // Recheck the task only if the removed item is relevant to it.
    if (state != BackpackState::IDLE &&
        taskManager.isItemRequired(itemType))
    {
        checkInventory();
    }
}

// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Picks up that an item was scanned but not necessarily placed into/out of the 
// backpack. Currently does nothing.
void Backpack::itemScanned(uint32_t tagID)
{
    // RFID/input subsystem integration point.
    // A scan does not automatically mean the item was added.
    // Calls either itemAdded or itemRemoved or perhaps also itemRegister.
    ItemType type = inventory.getItemType(tagID);

    if (type == ItemType::Unknown)
    {
        BackpackEvent event{};

        event.type = EventType::UnknownRFID;
        event.item = ItemType::Unknown;
        event.task = taskManager.getCurrentTask();

        eventGenerator.emit(event);

        return;
    }

    // Known tag.
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Get the current active task if any
// Helper function, returns the current task type
TaskType Backpack::getCurrentTask() const
{
    return taskManager.getCurrentTask();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Get the next required item for the currently active task
// Helper function, returns the current item type
ItemType Backpack::getNextRequiredItem() const
{
    return taskManager.getNextRequiredItem();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Check if a task is currently active.
// Returns true if yes.
bool Backpack::isTaskActive() const
{
    return state != BackpackState::IDLE;
    // Could also implament by calling the TaskManager::isTaskActive()
    // return taskManager.isTaskActive();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Check if the current task has all necessary items and is considered complete
// Returns true if complete
bool Backpack::isTaskComplete() const
{
    return taskManager.isTaskComplete();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Task manager query if an item type is required for the current active task
bool Backpack::isItemRequired(ItemType type) const
{
    return taskManager.isItemRequired(type);
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Check if there is an event ready
bool Backpack::hasEvent() const
{
    return eventGenerator.hasEvent();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Retrieve the last event generated by the FSM
BackpackEvent Backpack::getEvent()
{
    return eventGenerator.getEvent();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

// Clears the events currenlty in the genertor. 
void Backpack::clearEvents()
{
    eventGenerator.clear();
}
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++